import React from 'react';
import styled from 'styled-components';

const ProjectsSection = styled.section`
  width: 100%;
  padding: 4rem 0 2rem 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  background: ${({ theme }) => theme.bg};
`;

const ProjectsGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
  gap: 2.5rem;
  width: 90%;
  max-width: 1200px;
  margin: 0 auto;
`;

const ProjectCard = styled.div`
  background: #111;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 2px 16px 0 rgba(0,0,0,0.12);
  display: flex;
  flex-direction: column;
  align-items: stretch;
  transition: transform 0.18s cubic-bezier(0.4,0,0.2,1), box-shadow 0.18s cubic-bezier(0.4,0,0.2,1);
  will-change: transform;
  ${({ $angle, $offset }) => `
    transform: rotate(${$angle}deg) translateY(${$offset}px);
  `}
  &:hover {
    transform: scale(1.035) rotate(0deg) translateY(-2px);
    box-shadow: 0 6px 32px 0 rgba(0,0,0,0.18);
    z-index: 2;
  }
`;

const ProjectImage = styled.div`
  width: 100%;
  aspect-ratio: 4/3;
  background: #222;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  color: #aaa;
  font-weight: 500;
`;

const ProjectInfo = styled.div`
  padding: 1.2rem 1.5rem 1.5rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  background: #fff;
  text-align: center;
  margin-top: auto;
`;

const ProjectTitle = styled.h3`
  color: #fff;
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
`;

const ProjectDesc = styled.p`
  color: #575252ff;
  font-size: 1rem;
  margin-bottom: 0.5rem;
`;

// Placeholder images and info
const projects = [
  {
    title: 'SaaS Dashboard',
    desc: 'Modern dashboard UI for SaaS analytics.',
    img: '/images/original-53c3fa50f57e2df119c45f7567f5887e.webp',
  },
  {
    title: 'Creative Agency',
    desc: 'Portfolio site for a creative agency.',
    img: '/images/image.2.webp',
  },
  {
    title: 'Medical App',
    desc: 'UI for a healthcare mobile app.',
    img: '/images/image.3.webp',
  },
  {
    title: 'Finance Tool',
    desc: 'Clean UI for a finance dashboard.',
    img: '/images/image.4.webp',
  },
  {
    title: 'Travel Platform',
    desc: 'Landing page for a travel booking platform.',
    img: '/images/image.5.webp',
  },
  {
    title: 'Outdoor Blog',
    desc: 'Blog UI for outdoor adventures.',
    img: '/images/image.6.webp',
  },
];

const Projects = () => (
  <ProjectsSection id="projects">
    <ProjectsGrid>
      {projects.map((project, idx) => {
        // Alternate angles and offsets for a 'breaking' collage look
        const angles = [-4, 3, -2, 5, -3, 2];
        const offsets = [-10, 12, -6, 14, -8, 10];
        const angle = angles[idx % angles.length];
        const offset = offsets[idx % offsets.length];
        return (
          <ProjectCard key={idx} $angle={angle} $offset={offset}>
            <ProjectImage as="img" src={project.img} alt={project.title} />
            <ProjectInfo>
              <ProjectTitle>{project.title}</ProjectTitle>
              <ProjectDesc>{project.desc}</ProjectDesc>
            </ProjectInfo>
          </ProjectCard>
        );
      })}
    </ProjectsGrid>
  </ProjectsSection>
);

export default Projects;
